// AI DISCLAIMER: All of the text in this file was generated by AI.
// Adversary survey-class core test (2026-11-13): see bad_reorg_in_block.h.
// Chain: genesis (hf1); 17 miner + 60 rewind blocks (hf2 — v1 coinbases so the
// outputs carry real amounts in the per-amount index); the hf16 fork point
// blk_A (h78); then
//   main:   blk_A -> blk_B (h79, carries the valid tx T)
//   alt:    blk_A -> blk_C (h79) -> blk_D (h80)  — one block longer: switch
// After the switch blk_B is popped and T returns to the pool with a verID from
// the current view. The post-switch block blk_E (h81) carrying T is ACCEPTED
// (the re-mined valid tx re-validates). Then T' — an independent spend of the
// neighbouring pooled output, so its ring is exactly T's 16 pooled outputs —
// with a BROKEN CLSAG is pool-submitted (kept-by-block: stored unvalidated)
// and the block blk_F carrying it must be REFUSED: the reorg must not have
// left any verID state that lets a bad tx ride T's coat-tails.

#include "bad_reorg_in_block.h"

#include "chaingen.h"
#include "cryptonote_core/cryptonote_core.h"
#include "cryptonote_basic/cryptonote_format_utils.h"
#include "ringct/rctSigs.h"
#include "ringct/rctOps.h"

using namespace epee;
using namespace cryptonote;

static const size_t N_MINER_BLOCKS = 17;   // blocks h1..h17, one 4e9 coinbase output each
static const uint8_t EARLY_HF = 2;         // early chain: v1 coinbases so outputs are indexed by real amount
static const uint8_t TEST_HF = 16;         // the hf of the tested blocks
static const uint64_t MIN_SPEND_AMOUNT = 10000000000ULL;  // ~6x the hf16 min fee for a 16-ring BP+ tx
static const size_t RING_SIZE = 16;        // mixin 15 at hf16
static const uint64_t DUST_OUT = 5000;

namespace
{
  struct out_ref
  {
    size_t block_idx;   // index into the miner-block array
    size_t vout_idx;    // index of the output within that coinbase
    crypto::public_key key;
  };

  // Build one spend of a pooled coinbase output: ring of RING_SIZE consecutive
  // pooled outputs containing the real one, two dust outputs, fee = remainder.
  // Returns the fee. (Same construction as bad_tx_in_block.cpp; duplicated here
  // so the reorg family is self-contained.)
  uint64_t build_spend(const account_keys &sender,
      const std::vector<out_ref> &pool, uint64_t amount, const out_ref &real,
      const crypto::public_key &real_tx_pub_key, transaction &tx)
  {
    tx_source_entry src;
    src.amount = amount;
    // push_output's first argument is the output's per-amount global index,
    // which here equals the pool position (pool holds this amount's outputs in
    // chain order from the first block, so nothing shifts the numbering). The
    // ring is a window of RING_SIZE consecutive indices containing the real
    // output, pushed in ascending order: key_offsets are relative deltas of the
    // sorted indices, and the signature columns must line up with the keys the
    // core resolves from those offsets.
    CHECK_AND_ASSERT_MES(pool.size() >= RING_SIZE, 0, "pool too small for a ring");
    size_t real_pos_pool = (size_t)-1;
    for (size_t k = 0; k < pool.size(); ++k)
      if (pool[k].block_idx == real.block_idx && pool[k].vout_idx == real.vout_idx)
        { real_pos_pool = k; break; }
    CHECK_AND_ASSERT_MES(real_pos_pool != (size_t)-1, 0, "real output not in pool");
    const size_t window_start = real_pos_pool >= RING_SIZE - 1 ? real_pos_pool - (RING_SIZE - 1) : 0;
    CHECK_AND_ASSERT_MES(window_start + RING_SIZE <= pool.size(), 0, "ring window overruns pool");
    size_t real_pos = RING_SIZE;
    for (size_t m = 0; m < RING_SIZE; ++m)
    {
      const out_ref &oref = pool[window_start + m];
      src.push_output(window_start + m, oref.key, amount);
      if (oref.block_idx == real.block_idx && oref.vout_idx == real.vout_idx)
        real_pos = m;
    }
    CHECK_AND_ASSERT_MES(real_pos < RING_SIZE, 0, "real output missing from ring");
    src.real_output = real_pos;
    src.real_output_in_tx_index = real.vout_idx;
    src.real_out_tx_key = real_tx_pub_key;
    src.mask = rct::identity();
    src.rct = false;

    tx_destination_entry td;
    td.addr = sender.m_account_address;
    td.amount = DUST_OUT;
    std::vector<tx_destination_entry> destinations;
    destinations.push_back(td);
    destinations.push_back(td);

    std::vector<tx_source_entry> sources{src};
    crypto::secret_key tx_key;
    std::vector<crypto::secret_key> additional_tx_keys;
    std::unordered_map<crypto::public_key, cryptonote::subaddress_index> subaddresses;
    subaddresses[sender.m_account_address.m_spend_public_key] = {0, 0};
    const rct::RCTConfig rct_config = { rct::RangeProofPaddedBulletproof, 4 };
    const bool r = construct_tx_and_get_tx_key(sender, subaddresses, sources,
        destinations, boost::none, std::vector<uint8_t>(), tx, tx_key, additional_tx_keys,
        true, rct_config, true /* use_view_tags: hf16 requires tagged outputs */);
    CHECK_AND_ASSERT_MES(r, 0, "failed to construct transaction");
    return amount - 2 * DUST_OUT;
  }

  // Break the CLSAG (bad_tx_in_block's defect case 3): the ring-membership
  // signature is input-side state — it passes non-input consensus, so the
  // kept-by-block pool stores the tx UNVALIDATED and the BLOCK path is the
  // first to actually verify it.
  bool break_clsag(transaction &tx)
  {
    if (tx.rct_signatures.p.CLSAGs.empty() || tx.rct_signatures.p.CLSAGs[0].s.empty())
      return false;
    tx.rct_signatures.p.CLSAGs[0].s[0] = rct::skGen();
    return true;
  }
}

gen_bad_reorg_in_block::gen_bad_reorg_in_block()
{
  REGISTER_CALLBACK_METHOD(gen_bad_reorg_in_block, mark_invalid_tx);
  REGISTER_CALLBACK_METHOD(gen_bad_reorg_in_block, mark_invalid_block);
  REGISTER_CALLBACK_METHOD(gen_bad_reorg_in_block, check_reorg);
  REGISTER_CALLBACK_METHOD(gen_bad_reorg_in_block, check_remined);
  REGISTER_CALLBACK_METHOD(gen_bad_reorg_in_block, check_final);
}

bool gen_bad_reorg_in_block::generate(std::vector<test_event_entry> &events) const
{
  uint64_t ts_start = 1338224400;

  GENERATE_ACCOUNT(miner_account);
  MAKE_GENESIS_BLOCK(events, blk_0, miner_account, ts_start);

  // tx events go out with relay_method::block (kept-by-block): T' failing
  // check_tx_inputs (broken CLSAG) is stored in the pool UNVALIDATED, so the
  // bad block's verification path is the first to really check it
  SET_EVENT_VISITOR_SETT(events, event_visitor_settings::set_txs_keeped_by_block);

  const uint64_t ts_step = DIFFICULTY_BLOCKS_ESTIMATE_TIMESPAN * 2;

  // 17 miner blocks + rewind, all mined by the same account
  block blocks[N_MINER_BLOCKS];
  const block *prev_block = &blk_0;
  for (size_t n = 0; n < N_MINER_BLOCKS; ++n)
  {
    CHECK_AND_ASSERT_MES(generator.construct_block_manually(blocks[n], *prev_block, miner_account,
        test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp | test_generator::bf_hf_version,
        EARLY_HF, EARLY_HF, prev_block->timestamp + ts_step,
        crypto::hash(), 0, transaction(), std::vector<crypto::hash>(), 0, 0, EARLY_HF),
        false, "Failed to generate miner block");
    events.push_back(blocks[n]);
    prev_block = blocks + n;
  }

  // rewind past the coinbase unlock window
  block blk_last = blocks[N_MINER_BLOCKS - 1];
  for (size_t i = 0; i < CRYPTONOTE_MINED_MONEY_UNLOCK_WINDOW; ++i)
  {
    block blk_r;
    CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_r, blk_last, miner_account,
        test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp | test_generator::bf_hf_version,
        EARLY_HF, EARLY_HF, blk_last.timestamp + ts_step,
        crypto::hash(), 0, transaction(), std::vector<crypto::hash>(), 0, 0, EARLY_HF),
        false, "Failed to generate rewind block");
    events.push_back(blk_r);
    blk_last = blk_r;
  }

  // collect the coinbase outputs of blocks h1..h17 by amount and pick one that
  // can fund a full ring: any amount with >= RING_SIZE+1 occurrences and
  // >= MIN_SPEND_AMOUNT (fee floor headroom)
  std::map<uint64_t, std::vector<out_ref>> by_amount;
  for (size_t b = 0; b < N_MINER_BLOCKS; ++b)
    for (size_t i = 0; i < blocks[b].miner_tx.vout.size(); ++i)
    {
      if (blocks[b].miner_tx.vout[i].amount < MIN_SPEND_AMOUNT)
        continue;
      out_ref ref;
      ref.block_idx = b;
      ref.vout_idx = i;
      CHECK_AND_ASSERT_MES(get_output_public_key(blocks[b].miner_tx.vout[i], ref.key), false, "no output key");
      by_amount[blocks[b].miner_tx.vout[i].amount].push_back(ref);
    }
  std::vector<out_ref> pool;
  uint64_t spend_amount = 0;
  for (const auto &e : by_amount)
    if (e.second.size() >= RING_SIZE + 1 && e.second.size() > pool.size())
      { pool = e.second; spend_amount = e.first; }
  CHECK_AND_ASSERT_MES(!pool.empty(), false,
      "no hf2 coinbase amount occurs >= RING_SIZE+1 times with amount >= MIN_SPEND_AMOUNT");
  LOG_PRINT_L0("spend amount " << spend_amount << " pool size " << pool.size());

  // blk_A: the hf16 block — the FORK POINT of the reorg
  block blk_A;
  CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_A, blk_last, miner_account,
      test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp | test_generator::bf_hf_version,
      TEST_HF, TEST_HF, blk_last.timestamp + ts_step,
      crypto::hash(), 0, transaction(), std::vector<crypto::hash>(), 0, 0, TEST_HF),
      false, "Failed to generate the hf16 fork-point block");
  events.push_back(blk_A);
  blk_last = blk_A;

  // T: a valid spend of pooled output 0 (first-mined on the losing chain)
  transaction tx_T;
  const uint64_t fee = build_spend(miner_account.get_keys(), pool, spend_amount, pool[0],
      get_tx_pub_key_from_extra(blocks[pool[0].block_idx].miner_tx), tx_T);
  CHECK_AND_ASSERT_MES(fee != 0, false, "failed to construct T");

  // T': independent spend of the NEIGHBOURING pooled output — pool[0] and
  // pool[1] sit in the same 16-output ring window, so T' references exactly
  // T's mix ring (the coat-tails scenario) while having its own key image and
  // its own tx hash
  transaction tx_Tp;
  CHECK_AND_ASSERT_MES(build_spend(miner_account.get_keys(), pool, spend_amount, pool[1],
      get_tx_pub_key_from_extra(blocks[pool[1].block_idx].miner_tx), tx_Tp) != 0,
      false, "failed to construct T'");
  CHECK_AND_ASSERT_MES(break_clsag(tx_Tp), false, "failed to break the CLSAG of T'");
  tx_Tp.invalidate_hashes();

  // main chain: blk_B (h79) carries T; T is pool-submitted first (kept-by-block)
  std::vector<crypto::hash> tx_hashes_B{get_transaction_hash(tx_T)};
  block blk_B;
  CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_B, blk_A, miner_account,
      test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp |
      test_generator::bf_tx_hashes | test_generator::bf_hf_version | test_generator::bf_max_outs | test_generator::bf_tx_fees,
      TEST_HF, TEST_HF, blk_A.timestamp + ts_step,
      crypto::hash(), 0, transaction(), tx_hashes_B, 0, 6, TEST_HF, fee),
      false, "Failed to generate blk_B");
  events.push_back(tx_T);
  events.push_back(blk_B);

  // alt chain from the fork point: blk_C (h79) and blk_D (h80), both empty —
  // one block LONGER than the main chain, so the core switches to it and pops
  // blk_B (T returns to the pool)
  block blk_C, blk_D;
  CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_C, blk_A, miner_account,
      test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp | test_generator::bf_hf_version,
      TEST_HF, TEST_HF, blk_A.timestamp + ts_step,
      crypto::hash(), 0, transaction(), std::vector<crypto::hash>(), 0, 0, TEST_HF),
      false, "Failed to generate blk_C");
  events.push_back(blk_C);
  CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_D, blk_C, miner_account,
      test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp | test_generator::bf_hf_version,
      TEST_HF, TEST_HF, blk_C.timestamp + ts_step,
      crypto::hash(), 0, transaction(), std::vector<crypto::hash>(), 0, 0, TEST_HF),
      false, "Failed to generate blk_D");
  events.push_back(blk_D);
  DO_CALLBACK(events, "check_reorg");

  // POST-SWITCH ACCEPT: the next block on the winning chain re-mines T — the
  // popped tx re-validates (verID hit on the current view, or a full re-verify)
  std::vector<crypto::hash> tx_hashes_E{get_transaction_hash(tx_T)};
  block blk_E;
  CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_E, blk_D, miner_account,
      test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp |
      test_generator::bf_tx_hashes | test_generator::bf_hf_version | test_generator::bf_max_outs | test_generator::bf_tx_fees,
      TEST_HF, TEST_HF, blk_D.timestamp + ts_step,
      crypto::hash(), 0, transaction(), tx_hashes_E, 0, 6, TEST_HF, fee),
      false, "Failed to generate blk_E");
  events.push_back(blk_E);
  DO_CALLBACK(events, "check_remined");

  // POST-SWITCH REFUSE: T' is pool-submitted (stored unvalidated by the
  // kept-by-block path) and the block carrying it must be refused — the reorg
  // must not have left a verID / cache state that lets a bad tx ride T's
  // coat-tails on the same ring
  DO_CALLBACK(events, "mark_invalid_tx");
  events.push_back(tx_Tp);
  std::vector<crypto::hash> tx_hashes_F{get_transaction_hash(tx_Tp)};
  block blk_F;
  CHECK_AND_ASSERT_MES(generator.construct_block_manually(blk_F, blk_E, miner_account,
      test_generator::bf_major_ver | test_generator::bf_minor_ver | test_generator::bf_timestamp |
      test_generator::bf_tx_hashes | test_generator::bf_hf_version | test_generator::bf_max_outs | test_generator::bf_tx_fees,
      TEST_HF, TEST_HF, blk_E.timestamp + ts_step,
      crypto::hash(), 0, transaction(), tx_hashes_F, 0, 6, TEST_HF, fee),
      false, "Failed to generate blk_F");
  DO_CALLBACK(events, "mark_invalid_block");
  events.push_back(blk_F);

  DO_CALLBACK(events, "check_final");
  return true;
}

// expected chain heights (c.get_current_blockchain_height() = block count)
static const size_t H_FORK = 1 + N_MINER_BLOCKS + CRYPTONOTE_MINED_MONEY_UNLOCK_WINDOW + 1; // after blk_A
static const size_t H_SWITCH = H_FORK + 2; // after blk_D (alt one block longer took over)
static const size_t H_REMINED = H_SWITCH + 1; // after blk_E
// event-list indices (fixed by generate()'s push order): miner account,
// genesis, 17 miner, 60 rewind, blk_A, then the tx/block sequence
static const size_t IDX_TX_T = 2 + N_MINER_BLOCKS + CRYPTONOTE_MINED_MONEY_UNLOCK_WINDOW + 1;
// tx_Tp sits 8 events after tx_T: blk_B, blk_C, blk_D, cb(check_reorg),
// blk_E, cb(check_remined), cb(mark_invalid_tx)
static const size_t IDX_TX_TP = IDX_TX_T + 8;

bool gen_bad_reorg_in_block::check_reorg(cryptonote::core &c, size_t ev_index, const std::vector<test_event_entry> &events)
{
  DEFINE_TESTS_ERROR_CONTEXT("gen_bad_reorg_in_block::check_reorg");
  // the switch happened: the alt chain (one block longer) is canonical
  CHECK_EQ(H_SWITCH, c.get_current_blockchain_height());
  LOG_PRINT_L0("reorg: alternative blocks count " << c.get_alternative_blocks_count());
  CHECK_TEST_CONDITION(c.get_alternative_blocks_count() >= 1);
  // blk_D (pushed right before this callback) is the new tip
  CHECK_TEST_CONDITION(ev_index >= 1);
  std::vector<block> chain;
  CHECK_TEST_CONDITION(c.get_blocks(0, 10000, chain));
  CHECK_TEST_CONDITION(!chain.empty());
  CHECK_TEST_CONDITION(chain.back() == boost::get<block>(events[ev_index - 1]));
  // blk_B was popped: T is NOT in the chain and IS back in the pool
  const crypto::hash tx_hash = get_transaction_hash(boost::get<transaction>(events[IDX_TX_T]));
  CHECK_TEST_CONDITION(!c.get_blockchain_storage().have_tx(tx_hash));
  const size_t n_pool = c.get_pool_transactions_count();
  CHECK_EQ(1, n_pool);
  return true;
}

bool gen_bad_reorg_in_block::check_remined(cryptonote::core &c, size_t ev_index, const std::vector<test_event_entry> &events)
{
  DEFINE_TESTS_ERROR_CONTEXT("gen_bad_reorg_in_block::check_remined");
  // the post-switch block carrying T was accepted
  CHECK_EQ(H_REMINED, c.get_current_blockchain_height());
  CHECK_TEST_CONDITION(ev_index >= 1);
  std::vector<block> chain;
  CHECK_TEST_CONDITION(c.get_blocks(0, 10000, chain));
  CHECK_TEST_CONDITION(!chain.empty());
  CHECK_TEST_CONDITION(chain.back() == boost::get<block>(events[ev_index - 1]));
  // T is on the chain again and the pool is empty of it
  const crypto::hash tx_hash = get_transaction_hash(boost::get<transaction>(events[IDX_TX_T]));
  CHECK_TEST_CONDITION(c.get_blockchain_storage().have_tx(tx_hash));
  const size_t n_pool = c.get_pool_transactions_count();
  CHECK_EQ(0, n_pool);
  return true;
}

bool gen_bad_reorg_in_block::check_final(cryptonote::core &c, size_t, const std::vector<test_event_entry> &events)
{
  DEFINE_TESTS_ERROR_CONTEXT("gen_bad_reorg_in_block::check_final");
  // the refused block changed nothing: the chain keeps the post-switch height
  CHECK_EQ(H_REMINED, c.get_current_blockchain_height());
  // T stays mined; the defective T' was never written to the blockchain
  const crypto::hash tx_hash = get_transaction_hash(boost::get<transaction>(events[IDX_TX_T]));
  const crypto::hash tx_prime_hash = get_transaction_hash(boost::get<transaction>(events[IDX_TX_TP]));
  CHECK_TEST_CONDITION(tx_prime_hash != tx_hash);
  CHECK_TEST_CONDITION(c.get_blockchain_storage().have_tx(tx_hash));
  CHECK_TEST_CONDITION(!c.get_blockchain_storage().have_tx(tx_prime_hash));
  // T' is NOT dropped by the refusal: the kept-by-block pool still holds it
  // (unvalidated); T itself was re-mined out of the pool at check_remined
  const size_t n_pool = c.get_pool_transactions_count();
  MDEBUG("final pool count: " << n_pool);
  CHECK_EQ(1, n_pool);
  return true;
}
